<script>export let data;</script>
<section class="page"><div class="eyebrow">LOST & FOUND</div><h1>Help bring them home.</h1><p class="sub">Browse community reports or share a missing/found animal.</p><div class="toolbar"><form><input name="q" value={data.filters.q} placeholder="Search location, name, details..." /><select name="type"><option value="all">Lost + Found</option><option value="lost" selected={data.filters.type==='lost'}>Lost</option><option value="found" selected={data.filters.type==='found'}>Found</option></select><select name="animal"><option value="all">All animals</option><option value="dog" selected={data.filters.animal==='dog'}>Dogs</option><option value="cat" selected={data.filters.animal==='cat'}>Cats</option></select><button class="btn primary" type="submit">Search</button></form><a class="btn light" href="/lost-found/new">+ Report animal</a></div>{#if data.reports.length}<div class="masonry">{#each data.reports as item}<a class="card" href={`/report/${item.id}`}><div>{#if item.image_url}<img src={item.image_url} alt={item.title}/>{:else}<div class="image-placeholder">{item.animal_type==='cat'?'🐱':'🐶'}</div>{/if}</div><div class="card-body"><div class="meta"><span>{item.type} · {item.animal_type}</span><span>active</span></div><h3>{item.title}</h3><p>{item.description}</p><small>📍 {item.location}</small></div></a>{/each}</div>{:else}<div class="empty">No reports match your search yet.</div>{/if}</section>
